const slotsWithAvailability = `-- name: SlotsWithAvailability :many
SELECT s.id, s.org_id, s.listing_id, s.starts_at, s.duration_min, s.capacity, s.note, s.created_at, (SELECT count(*) FROM viewing_bookings b WHERE b.slot_id = s.id AND b.cancelled_at IS NULL)::int AS booked
FROM viewing_slots s
WHERE s.listing_id = $1 AND s.starts_at > now()
ORDER BY s.starts_at
`

type SlotsWithAvailabilityRow struct {
	ID          uuid.UUID `json:"id"`
	OrgID       uuid.UUID `json:"org_id"`
	ListingID   uuid.UUID `json:"listing_id"`
	StartsAt    time.Time `json:"starts_at"`
	DurationMin int32     `json:"duration_min"`
	Capacity    int32     `json:"capacity"`
	Note        string    `json:"note"`
	CreatedAt   time.Time `json:"created_at"`
	Booked      int32     `json:"booked"`
}

// Upcoming slots with the number of active bookings (system context: the
// count must include other applicants' bookings).
func (q *Queries) SlotsWithAvailability(ctx context.Context, listingID uuid.UUID) ([]SlotsWithAvailabilityRow, error) {
	rows, err := q.db.Query(ctx, slotsWithAvailability, listingID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SlotsWithAvailabilityRow{}
	for rows.Next() {
		var i SlotsWithAvailabilityRow
		if err := rows.Scan(
			&i.ID,
			&i.OrgID,
			&i.ListingID,
			&i.StartsAt,
			&i.DurationMin,
			&i.Capacity,
			&i.Note,
			&i.CreatedAt,
			&i.Booked,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

